insert into public.listings (slug, kind, owner_id, status, price, data) values ('pocket-ledger', 'template', '62b2f375-3ae0-4741-80e8-c4b7d7debefd', 'live', 15800, '{"slug":"pocket-ledger","name":"Pocket Ledger 記帳本","tagline":"離線優先的個人記帳 App，附月結圖表和訂閱解鎖。","category":"finance","creator":"kaylee-builds","price":158,"currency":"HKD","rating":4.8,"reviewCount":46,"sales":612,"updatedAt":"2026-10-18","createdAt":"2026-06-02","stack":["Expo","Supabase","RevenueCat","Claude Code"],"platforms":["iOS","Android","Web"],"license":"commercial","cover":{"from":"#5b3fd6","to":"#9b7bff","icon":"wallet"},"screens":5,"features":["離線記帳，上線後自動同步","月結卡片和分類圖表","RevenueCat 訂閱解鎖進階分析","深色模式和 Dynamic Type"],"forWho":"想做第一個上架 App、又需要真實付款流程參考的獨立開發者。","requirements":["Supabase 免費帳戶","RevenueCat 免費帳戶","Apple Developer（US$99／年，上架時才需要）"],"story":[{"title":"定義資料模型","body":"先決定一筆記錄需要甚麼欄位：金額、分類、日期、備註。所有金額用整數「仙」儲存，避免浮點誤差。","prompt":{"tool":"Claude Code","text":"Create a Supabase migration for an `entries` table:\n- id uuid pk\n- user_id uuid references auth.users\n- amount_cents integer not null\n- category text not null\n- spent_at date not null\n- note text\nEnable RLS so users only see their own rows."},"pitfall":"一開始用 float 存金額，月結時差了 $0.01，之後全部改成整數。"},{"title":"首頁月結卡片","body":"首頁只放一張卡：本月支出、與上月比較、最大的三個分類。數字用 tabular-nums，切換月份時滾動到新值。","prompt":{"tool":"Claude Code","text":"Build a MonthSummaryCard component that shows total spend for the selected month, delta vs previous month, and the top 3 categories. Use theme tokens only."}},{"title":"離線優先同步","body":"記帳要在沒有網絡時都能用。本機寫入 MMKV 佇列，上線後批次上傳，伺服器以 updated_at 解決衝突。","pitfall":"同步失敗時曾經用空陣列覆蓋本機資料，用戶記錄全部消失。現在空回應一律不寫入。"},{"title":"RevenueCat 訂閱","body":"進階分析用訂閱解鎖。伺服器 webhook 收到事件後才更新權限，App 不自行判斷。"},{"title":"上架 App Store","body":"私隱標籤、刪除帳戶入口、TestFlight 測試帳戶說明，一次過準備好。"},{"title":"上架 Google Play","body":"個人帳戶要先完成 12 人、14 日的封閉測試。"}],"freePreviewSteps":2,"files":[{"name":"app","children":[{"name":"(tabs)","children":[{"name":"_layout.tsx","size":2140},{"name":"index.tsx","size":5320},{"name":"settings.tsx","size":3010}]},{"name":"_layout.tsx","size":1680}]},{"name":"src","children":[{"name":"components","children":[{"name":"Card.tsx","size":1820},{"name":"Button.tsx","size":2260}]},{"name":"lib","children":[{"name":"format.ts","size":940},{"name":"format.test.ts","size":1210}]},{"name":"sync","children":[{"name":"queue.ts","size":3880},{"name":"queue.test.ts","size":2950}]}]},{"name":"supabase","children":[{"name":"migrations","children":[{"name":"0001_init.sql","size":4420}]}]},{"name":"README.md","size":6240},{"name":"app.config.ts","size":1380},{"name":"package.json","size":2110}],"readme":"# Pocket Ledger\n\n1. `npm install`\n2. 複製 `.env.example` 為 `.env`，填入 Supabase URL\n3. `npx supabase db push`\n4. `npx expo run:ios`","reviews":[{"id":"r1","author":"Jamie L.","rating":5,"date":"2026-10-12","body":"README 寫得非常清楚，跟著做 20 分鐘就在手機上跑起來。製作經歷中的 prompt 直接可以用。","reply":"多謝！下個版本會加入深色模式截圖。"},{"id":"r2","author":"Wing","rating":4.5,"date":"2026-10-02","body":"同步那一段的踩坑分享很有用，省了我一個週末。"},{"id":"r3","author":"Alex T.","rating":4,"date":"2026-09-21","body":"架構乾淨，不過 Android 上鍵盤遮住輸入框，要自己修一下。"}],"versions":[{"version":"1.4.0","date":"2026-10-18","notes":"加入 Web 版和寬螢幕版面。"},{"version":"1.3.2","date":"2026-09-02","notes":"修正同步失敗時覆蓋本機資料的問題。"},{"version":"1.0.0","date":"2026-06-02","notes":"首次上架。"}],"featured":true}'::jsonb) on conflict do nothing;
